/// <summary>
/// getLineAttributes' answer. A line not listed is PHYSICAL, own stock, counted normally.
/// </summary>
[DataContractAttribute]
class HSMobileOpsCountLineAttributesResponse
{
    boolean success;
    str     errorCode;
    List    lines;

}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Lines'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsCountLineAttributeRow))]
public List parmLines(List _value = lines)
{
    lines = _value;
    return lines;
}
